    ld4_h(p, v, pol); ld4_h(p + 4, v + 4, pol);
}
__device__ __forceinline__ void st8_h(float* p, const float* v, uint64_t pol) { st4_h(p, v, pol); st4_h(p + 4, v + 4, pol); }
