            int n_tok, float eps, cudaStream_t st) {
    const int n_cta = NG * ((n_tok + R - 1) / R);
    qk_rms_rtok<R, LDM, MINB><<<dim3(2u * (unsigned)n_cta), THREADS, 0, st>>>(q, k, wq, wk, qo, ko, n_cta, n_tok, eps);
